 renderSurvival();
 renderForaging();
 $('#abok-knot-grid').innerHTML=DATA.knots.map((k,i)=>`<button class="abok-knot-topic" data-knot-index="${i}" aria-label="Open ${esc(k.name)} guide"><img src="${esc(k.photo)}" alt="Photograph or reference image of ${esc(k.name)}" loading="lazy" onerror="this.closest('.abok-knot-topic').classList.add('photo-failed');this.hidden=true"><span>${esc(k.name)}</span></button>`).join('');
 const knotLesson=$('#abok-knot-lesson'); const showKnot=(i)=>{const k=DATA.knots[i]; if(!k||!knotLesson)return; knotLesson.innerHTML=`<div class="abok-knot-feature"><figure><img src="${esc(k.photo)}" alt="Reference image of ${esc(k.name)}" onerror="this.hidden=true;this.nextElementSibling.textContent='Reference photo unavailable — use the tying steps and trusted source links below.'"><figcaption>Reference image · Wikimedia Commons</figcaption></figure><div><p class="eyebrow">Useful outdoor knot</p><h3>${esc(k.name)}</h3><h4>Best used for</h4><p>${esc(k.use)}</p><div class="abok-knot-warning"><strong>Important limitation</strong><p>${esc(k.warning)}</p></div></div></div><div class="abok-knot-howto"><section><h4>How to tie it</h4><ol>${k.steps.map((x,n)=>`<li><b>${n+1}</b><span>${esc(x)}</span></li>`).join('')}</ol></section><aside><h4>Rope-path reference</h4><div class="abok-knot-diagram large"><svg viewBox="0 0 170 100" aria-hidden="true"><path d="${esc(k.path)}"/></svg></div><p>This simple line drawing is an orientation aid. Check the finished knot against the reference image and instructions.</p><h4>Trusted learning sources</h4><a href="https://rnli.org/-/media/rnli/downloads/tp-int-05_maritime_sar_manual_2019.pdf" target="_blank" rel="noopener">RNLI Ropework ↗</a><a href="https://www.animatedknots.com/scouting-knots" target="_blank" rel="noopener">Animated Knots reference ↗</a></aside></div>`; $$('.abok-knot-topic').forEach((b,n)=>b.classList.toggle('active',n===i));}; $$('.abok-knot-topic').forEach((b,i)=>b.addEventListener('click',()=>showKnot(i))); showKnot(0);
